examples.template:
MonarchButton({{trigger}}, variant: .danger) {
    step = 0
    isOpen = true
}
.sheet(isPresented: $isOpen) {
    NavigationStack {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Text({{description}})
                .monarchTextStyle(.body)
            if step < steps.count {
                MonarchStepper(steps, current: step, compact: .always)
            }
            Text(step < steps.count ? steps[step].label : {{done.title}})
                .monarchTextStyle(.subheading)
                .accessibilityAddTraits(.isHeader)
            switch step {
            case 0:
                HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
                    Text("•")
                    Text({{review.items.0}})
                }
                .monarchTextStyle(.body)
                HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
                    Text("•")
                    Text({{review.items.1}})
                }
                .monarchTextStyle(.body)
            case 1:
                Text({{export.description}}).monarchTextStyle(.body)
                Toggle({{export.label}}, isOn: $exported)
                    .toggleStyle(.monarchCheckbox)
                if !exported {
                    Text({{export.blocked}}).monarchTextStyle(.caption)
                }
            case 2:
                Text({{confirm.content}}).monarchTextStyle(.body)
            default:
                Text({{done.content}}).monarchTextStyle(.body)
            }
            Spacer(minLength: 0)
            HStack {
                if step > 0 && step < steps.count {
                    MonarchButton("Back") { step -= 1 }
                }
                Spacer(minLength: 0)
                if step < steps.count {
                    MonarchButton(
                        step == steps.count - 1 ? {{confirm.continueLabel}} : "Continue",
                        variant: step == steps.count - 1 ? .danger : .primary
                    ) {
                        step += 1
                    }
                    .disabled(step == 1 && !exported)
                } else {
                    MonarchButton("Close") { isOpen = false }
                }
            }
        }
        .padding(theme.spacing.space4)
        .navigationTitle({{title}})
        #if os(iOS)
        .navigationBarTitleDisplayMode(.inline)
        #endif
        .toolbar {
            ToolbarItem(placement: .cancellationAction) {
                Button("Cancel") { isOpen = false }
            }
        }
    }
    .interactiveDismissDisabled(step > 0 && step < steps.count)
    .presentationBackground(theme.colors.bgSurface)
}

