examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = true
@State private var step = 0
@State private var exported = false
private let steps = [
    MonarchStepperStep(id: "review", label: "What happens"),
    MonarchStepperStep(id: "export", label: "Keep a copy"),
    MonarchStepperStep(id: "confirm", label: "Close the project"),
]

examples.code:
MonarchButton("Close project", variant: .danger) {
    step = 0
    isOpen = true
}
.sheet(isPresented: $isOpen) {
    NavigationStack {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Text("Closing removes the project for everyone.")
                .monarchTextStyle(.body)
            if step < steps.count {
                MonarchStepper(steps, current: step, compact: .always)
            }
            Text(step < steps.count ? steps[step].label : "Project closed")
                .monarchTextStyle(.subheading)
                .accessibilityAddTraits(.isHeader)
            switch step {
            case 0:
                HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
                    Text("•")
                    Text("48 tasks are archived")
                }
                .monarchTextStyle(.body)
                HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
                    Text("•")
                    Text("6 people lose access")
                }
                .monarchTextStyle(.body)
            case 1:
                Text("Download the tasks and comments before you continue.").monarchTextStyle(.body)
                Toggle("I have downloaded a copy, or I do not need one", isOn: $exported)
                    .toggleStyle(.monarchCheckbox)
                if !exported {
                    Text("Tick the box to continue.").monarchTextStyle(.caption)
                }
            case 2:
                Text("You can reopen it from Archive for 30 days.").monarchTextStyle(.body)
            default:
                Text("It is in Archive.").monarchTextStyle(.body)
            }
            Spacer(minLength: 0)
            HStack {
                if step > 0 && step < steps.count {
                    MonarchButton("Back") { step -= 1 }
                }
                Spacer(minLength: 0)
                if step < steps.count {
                    MonarchButton(
                        step == steps.count - 1 ? "Close project" : "Continue",
                        variant: step == steps.count - 1 ? .danger : .primary
                    ) {
                        step += 1
                    }
                    .disabled(step == 1 && !exported)
                } else {
                    MonarchButton("Close") { isOpen = false }
                }
            }
        }
        .padding(theme.spacing.space4)
        .navigationTitle("Close project")
        #if os(iOS)
        .navigationBarTitleDisplayMode(.inline)
        #endif
        .toolbar {
            ToolbarItem(placement: .cancellationAction) {
                Button("Cancel") { isOpen = false }
            }
        }
    }
    .interactiveDismissDisabled(step > 0 && step < steps.count)
    .presentationBackground(theme.colors.bgSurface)
}
